using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;

class Program
{
    static void Check(bool value,string error){if(!value)throw new Exception(error);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(o,args);
    static void Seam(BackupEngine e,string name,object value)=>typeof(BackupEngine).GetProperty(name,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,value);
    static void Wait(Task t){var frame=new DispatcherFrame();t.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);t.GetAwaiter().GetResult();}
    static T Run<T>(Func<Task<T>> f)=>Task.Run(f).GetAwaiter().GetResult();
    static void Refuse(Action action){try{action();}catch(Exception e)when(e is IOException or UnauthorizedAccessException or InvalidDataException or OperationCanceledException){return;}throw new Exception("Expected refusal");}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var c in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var d in Logical(c))yield return d;}
    static Package Fixture(string dir)
    {
        var root=Path.Combine(dir,"input","Generated");Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"Game.exe"),"generated fixture; never execute");File.WriteAllBytes(Path.Combine(root,"data.bin"),new byte[2*1024*1024]);
        return new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=root,DetectedRoot=root,SearchRoot=Path.GetDirectoryName(root)!,Folder="Generated",Name="Generated",Alias="가상 게임"};
    }
    static (Package Game,BackupEngine Engine,BackupJob Job) Backed(string dir)
    {var p=Fixture(dir);var e=new BackupEngine(Path.Combine(dir,"backups"));return(p,e,Run(()=>e.CreateAsync(p,[])));}
    static (Package Game,LibraryStore Library,MoveJob Move,IdentityInventory Inventory) SelectiveRegisteredMove(string dir)
    {
        var p=Fixture(dir);Directory.CreateDirectory(Path.Combine(p.Source,"Extras"));File.WriteAllText(Path.Combine(p.Source,"Extras","keep.txt"),"excluded fixture");p.OmittedFolders=["Extras"];var library=new LibraryStore(Path.Combine(dir,"library"));library.Register(p,[],GameScanner.Scan(p.SearchRoot));p.Registered=true;
        var engine=new BackupEngine(Path.Combine(dir,"backups"));var backup=Run(()=>engine.CreateAsync(p,[]));var move=Run(()=>engine.MoveAsync(backup.Id,Path.Combine(dir,"target","Generated")));p.Source=move.Destination;p.DetectedRoot=p.Source;p.OmittedFolders=[];return(p,library,move,LibraryStore.Inspect(GameScanner.Scan(p.Source)));
    }
    static void Manifest(BackupEngine e,BackupJob j){File.WriteAllText(Path.Combine(e.Root,j.Id,"manifest.json"),JsonSerializer.Serialize(j));}
    static void MoveRecord(BackupEngine e,BackupJob j,string state)
    {var m=new MoveJob{BackupId=j.Id,Source=j.SourceRoot,Destination=Path.Combine(Path.GetDirectoryName(e.Root)!,"target","Generated"),Status=state};var d=Path.Combine(e.Root,j.Id,"moves");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,m.Id+".json"),JsonSerializer.Serialize(m));}
    static void RestoreRecord(BackupEngine e,BackupJob j,string state)
    {var r=new RestoreJob{BackupId=j.Id,Status=state};r.TargetContainer=Path.Combine(Path.GetDirectoryName(e.Root)!,"restore-"+r.Id);var d=Path.Combine(e.Root,j.Id,"restores");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,r.Id+".json"),JsonSerializer.Serialize(r));}
    static MainWindow Window(string dir,Package p)
    {
        var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var doc=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};
        var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(doc);var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",doc);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",doc.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static void CancelNextDialog(Action action)
    {
        var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};bool found=false;timer.Tick+=(_,_)=>{var dialog=Application.Current.Windows.OfType<AppDialog>().LastOrDefault();if(dialog==null)return;found=true;timer.Stop();dialog.Close();};timer.Start();try{action();Check(found,"Expected change confirmation was not shown");}finally{timer.Stop();}
    }
    static void Capture(FrameworkElement body,string path,double width,double height)
    {
        body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();
        foreach(var button in Logical(body).OfType<Button>().Where(b=>b.IsVisible&&b.ActualWidth>0)){var at=button.TranslatePoint(new Point(),body);Check(at.X>=-1&&at.X+button.ActualWidth<=width+1,"Clipped action: "+button.Content);}
        var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var d=bg.RenderOpen())d.DrawRectangle(Brushes.White,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var stream=File.Create(path);png.Save(stream);
    }
    [STAThread]static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var report=Path.GetFullPath(args[1]);var gallery=Path.Combine(root,"screens");Directory.CreateDirectory(gallery);
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        var results=new List<object>();var failed=0;
        void Test(string name,Action<string> action){var dir=Path.Combine(root,Guid.NewGuid().ToString("N")[..8]);Directory.CreateDirectory(dir);try{action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;results.Add(new{name,passed=false,error=e.ToString()});Console.WriteLine("FAIL "+name+" "+e.Message);}}
        Test("incomplete-backup-needs-explicit-discard",dir=>{var f=Backed(dir);f.Job.Status="Interrupted";Manifest(f.Engine,f.Job);Refuse(()=>f.Engine.DeleteBackups([f.Job.Id]));Check(!f.Engine.Inventory().Single().Selectable&&f.Engine.Inventory(true).Single().Selectable,"Incomplete deletion was automatic or has no explicit path");f.Engine.DeleteBackups([f.Job.Id],true);Check(f.Engine.Load(f.Job.Id).Status=="Deleted"&&File.Exists(Path.Combine(f.Game.Source,"Game.exe")),"Discard changed source or did not persist tombstone");});
        Test("source-changed-failed-backup-can-be-discarded",dir=>{var p=Fixture(dir);var e=new BackupEngine(Path.Combine(dir,"backups"));using var cts=new CancellationTokenSource();Seam(e,"Checkpoint",(Action<string>)(phase=>{if(phase=="backup-file-committed")cts.Cancel();}));Refuse(()=>Run(()=>e.CreateAsync(p,[],cancellation:cts.Token)));Seam(e,"Checkpoint",(Action<string>)(_=>{}));var j=e.ListJobs(false).Single();File.WriteAllText(Path.Combine(p.Source,"new.txt"),"user changed source");Refuse(()=>Run(()=>e.ResumeAsync(j.Id)));e.DeleteBackups([j.Id],true);Check(File.ReadAllText(Path.Combine(p.Source,"new.txt"))=="user changed source"&&e.Load(j.Id).Status=="Deleted","Source change cannot be cleared safely");});
        Test("invalid-backup-can-be-discarded-without-touching-source",dir=>{var f=Backed(dir);File.WriteAllText(Path.Combine(f.Engine.Payload(f.Job),"data.bin"),"tampered");Refuse(()=>Run(()=>f.Engine.VerifyAsync(f.Job.Id)));Check(f.Engine.Load(f.Job.Id).Status=="Invalid","Invalid not recorded");f.Engine.DeleteBackups([f.Job.Id],true);Check(new FileInfo(Path.Combine(f.Game.Source,"data.bin")).Length==2*1024*1024,"Source damaged");});
        Test("discard-still-protects-pending-move",dir=>{var f=Backed(dir);f.Job.Status="Failed";Manifest(f.Engine,f.Job);MoveRecord(f.Engine,f.Job,"RecoveryRequired");Refuse(()=>f.Engine.DeleteBackups([f.Job.Id],true));Check(!f.Engine.Inventory(true).Single().Selectable,"Move recovery dependency became selectable");});
        Test("discard-still-protects-pending-restore",dir=>{var f=Backed(dir);RestoreRecord(f.Engine,f.Job,"Failed");Refuse(()=>f.Engine.DeleteBackups([f.Job.Id],true));Check(f.Engine.Inventory(true).Single().Protection!.Contains("복원"),"Restore dependency unprotected");});
        Test("discard-still-protects-rename-recovery-and-active-backup",dir=>{var f=Backed(dir);f.Job.RetainedForRecovery=true;f.Job.Status="Failed";Manifest(f.Engine,f.Job);Refuse(()=>f.Engine.DeleteBackups([f.Job.Id],true));f.Job.RetainedForRecovery=false;f.Job.Status="Copying";Manifest(f.Engine,f.Job);Refuse(()=>f.Engine.DeleteBackups([f.Job.Id],true));Check(Directory.Exists(f.Engine.Payload(f.Job)),"Protected backup removed");});
        Test("discard-checks-all-selections-before-removal",dir=>{var f=Backed(dir);f.Job.Status="Failed";Manifest(f.Engine,f.Job);var p=Fixture(Path.Combine(dir,"other"));var other=Run(()=>f.Engine.CreateAsync(p,[]));MoveRecord(f.Engine,other,"Interrupted");Refuse(()=>f.Engine.DeleteBackups([f.Job.Id,other.Id],true));Check(Directory.Exists(f.Engine.Payload(f.Job))&&f.Engine.Load(f.Job.Id).Status=="Failed","First backup deleted before checking protected second");});
        Test("discard-respects-operation-lock",dir=>{var f=Backed(dir);f.Job.Status="Failed";Manifest(f.Engine,f.Job);using(var held=new FileStream(Path.Combine(f.Engine.Root,"operation.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))Refuse(()=>f.Engine.DeleteBackups([f.Job.Id],true));Check(Directory.Exists(f.Engine.Payload(f.Job)),"Operation lock bypassed");});
        Test("restore-resume-requires-only-remaining-space",dir=>{var f=Backed(dir);using var cts=new CancellationTokenSource();Seam(f.Engine,"Checkpoint",(Action<string>)(phase=>{if(phase=="restore-file-committed")cts.Cancel();}));Refuse(()=>Run(()=>f.Engine.RestoreAsync(f.Job.Id,Path.Combine(dir,"restored"),cancellation:cts.Token)));var r=f.Engine.ListRestores(f.Job.Id).Single();var target=f.Engine.RestoredPayload(f.Job,r);var existing=f.Job.Files.Where(file=>File.Exists(Path.Combine(target,file.RelativePath))).Sum(file=>file.Length);Check(existing>0,"No copied file to exercise resumption");Seam(f.Engine,"Checkpoint",(Action<string>)(_=>{}));Seam(f.Engine,"AvailableBytesOverride",(Func<long>)(()=>f.Job.TotalBytes-existing+16L*1024*1024));var resumed=Run(()=>f.Engine.ResumeRestoreAsync(f.Job.Id,r.Id));Check(resumed.Status=="Completed","Restoration blocked by already-used space");});
        Test("restore-resume-never-reuses-changed-file-for-space",dir=>{var f=Backed(dir);using var cts=new CancellationTokenSource();Seam(f.Engine,"Checkpoint",(Action<string>)(phase=>{if(phase=="restore-file-committed")cts.Cancel();}));Refuse(()=>Run(()=>f.Engine.RestoreAsync(f.Job.Id,Path.Combine(dir,"restored"),cancellation:cts.Token)));var r=f.Engine.ListRestores(f.Job.Id).Single();var target=f.Engine.RestoredPayload(f.Job,r);var path=Directory.GetFiles(target).First();File.WriteAllText(path,"user-edited restore");Seam(f.Engine,"Checkpoint",(Action<string>)(_=>{}));Refuse(()=>Run(()=>f.Engine.ResumeRestoreAsync(f.Job.Id,r.Id)));Check(File.ReadAllText(path)=="user-edited restore","Changed restore overwritten");});
        Test("deleted-backup-hides-impossible-move-undo",dir=>{var f=Backed(dir);var move=Run(()=>f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Generated")));f.Engine.DeleteBackups([f.Job.Id]);var history=new WorkHistoryStore(Path.Combine(dir,"history.json")).Refresh([f.Engine.Root]);var record=history.Records.Single(r=>r.Kind=="Move");Check(record.BackupRemoved,"Removed backup absent from move summary");var w=Window(dir,f.Game);try{var card=(Border)Call(w,"HistoryCard",record)!;Check(!Logical(card).OfType<Button>().Any(b=>b.Content as string=="원래 위치로 되돌리기"),"Impossible undo remains offered");Check(Logical(card).OfType<TextBlock>().Any(t=>t.Text.Contains("백업이 삭제")),"No reason for unavailable undo");Capture(card,Path.Combine(gallery,"deleted-backup-move.png"),680,380);}finally{Close(w);}});
        Test("interrupted-deletion-offers-delete-retry",dir=>{var p=Fixture(dir);var w=Window(dir,p);try{var record=new WorkRecord{Root=Path.Combine(dir,"backups"),Kind="Backup",JobId=Guid.NewGuid().ToString("N"),State="DeleteFailed",Title="가상 게임",Availability="Connected",Verified=true,BackupRemoved=true};var card=(Border)Call(w,"HistoryCard",record)!;var labels=Logical(card).OfType<Button>().Select(b=>b.Content as string).ToList();Check(labels.Contains("삭제 다시 시도")&&!labels.Contains("다시 검증")&&!labels.Contains("백업 재개"),"Unusable verification/resume is still primary action");Capture(card,Path.Combine(gallery,"delete-retry.png"),680,380);}finally{Close(w);}});
        Test("backup-manager-shows-discardable-failure-without-success-label",dir=>{var f=Backed(dir);f.Job.Status="Failed";Manifest(f.Engine,f.Job);var w=Window(dir,f.Game);Window? manager=null;try{manager=(Window)Call(w,"BuildBackupManagerAt",f.Engine)!;manager.Show();Wait(Task.Delay(300));var body=(FrameworkElement)manager.Content;var labels=Logical(body).OfType<TextBlock>().Select(t=>t.Text).ToList();Check(labels.Any(t=>t.Contains("미완료 백업"))&&!labels.Any(t=>t=="실행 확인 전"),"Failure shown as a completed backup");Check(Logical(body).OfType<Button>().Any(b=>b.Content as string=="선택"&&b.IsEnabled),"Failed backup cannot be selected");Capture(body,Path.Combine(gallery,"backup-manager-incomplete.png"),850,650);}finally{manager?.Close();Close(w);}});
        Test("manual-backup-rechecks-changes-and-cancel-does-not-write",dir=>{var p=Fixture(dir);var w=Window(dir,p);try{File.WriteAllText(Path.Combine(p.Source,"Returned.exe"),"generated extra executable");CancelNextDialog(()=>Wait((Task)Call(w,"StartBackupBatchAsync",new List<Package>{p})!));Check(p.AddedExecutables.Count==1&&!Directory.Exists(Path.Combine(dir,"backups")),"Manual backup skipped fresh confirmation or wrote after cancel");}finally{Close(w);}});
        Test("manual-backup-rechecks-later-batch-item-before-copy",dir=>{var p=Fixture(dir);var w=Window(dir,p);try{var other=Fixture(Path.Combine(dir,"other"));var games=Get<List<Package>>(w,"packages");games.Add(other);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",games.Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());var engine=new BackupEngine(Path.Combine(dir,"backups"));var changed=false;Seam(engine,"Checkpoint",(Action<string>)(phase=>{if(!changed&&phase=="backup-copying"){changed=true;File.WriteAllText(Path.Combine(other.Source,"Returned.exe"),"added after confirmation");}}));Set(w,"backupEngineFactory",(Func<BackupEngine>)(()=>engine));Set(w,"intakeInProgress",true);Wait((Task)Call(w,"StartBackupBatchAsync",games)!);var run=Get<OperationStatus>(w,"operationStatus");Check(engine.ListJobs(false).Count==1&&run.Items.Any(i=>i.Id==other.Id&&i.State=="Failed"),"Changed later game was backed up without confirmation");Check(File.Exists(Path.Combine(other.Source,"Returned.exe")),"New source file changed");}finally{Close(w);}});
        Test("cancelled-backed-copy-cleans-temporary-game-data",dir=>{var f=Backed(dir);Seam(f.Engine,"ForceCopyMove",true);using var cts=new CancellationTokenSource();Seam(f.Engine,"Checkpoint",(Action<string>)(phase=>{if(phase=="Moving-chunk")cts.Cancel();}));Refuse(()=>Run(()=>f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved"),cancellation:cts.Token)));Check(File.Exists(Path.Combine(f.Game.Source,"Game.exe"))&&Directory.Exists(f.Engine.Payload(f.Job)),"Cancel removed source or backup");Check(!Directory.GetDirectories(Path.Combine(dir,"target"),".indierun-move-*").Any(),"Backed cancellation leaked temporary game copy");Check(f.Engine.ListMoves(false).Single().Status=="RolledBack","Safe cancellation not rolled back");});
        Test("cancelled-backed-copy-preserves-unrecognized-stage-file",dir=>{var f=Backed(dir);Seam(f.Engine,"ForceCopyMove",true);using var cts=new CancellationTokenSource();string? extra=null;Seam(f.Engine,"Checkpoint",(Action<string>)(phase=>{if(phase=="Moving-chunk"&&extra==null){var stage=Directory.GetDirectories(Path.Combine(dir,"target"),".indierun-move-*").Single();extra=Path.Combine(stage,"user-note.txt");File.WriteAllText(extra,"keep user file");cts.Cancel();}}));Refuse(()=>Run(()=>f.Engine.MoveAsync(f.Job.Id,Path.Combine(dir,"target","Moved"),cancellation:cts.Token)));Check(extra!=null&&File.ReadAllText(extra)=="keep user file"&&File.Exists(Path.Combine(f.Game.Source,"Game.exe"))&&Directory.Exists(f.Engine.Payload(f.Job)),"Cleanup removed unrelated stage data or survivor");var move=f.Engine.ListMoves(false).Single();Check(move.Status=="RecoveryRequired","Unresolved cleanup hidden as complete");File.Delete(extra!);Seam(f.Engine,"Checkpoint",(Action<string>)(_=>{}));Check(Run(()=>f.Engine.UndoMoveAsync(f.Job.Id,move.Id)).Status=="RolledBack","Cleanup could not recover after conflict removed");});
        Test("previous-location-recovers-crash-era-records",dir=>{var f=Backed(dir);f.Job.Status="Copying";f.Job.SourceVerified=false;Manifest(f.Engine,f.Job);MoveRecord(f.Engine,f.Job,"Running");RestoreRecord(f.Engine,f.Job,"Restoring");var doc=new WorkHistoryStore(Path.Combine(dir,"history.json")).Refresh([f.Engine.Root]);Check(doc.Records.All(r=>r.State=="Interrupted"),"Previous location remains stuck in stale active state");});
        Test("history-refresh-never-interrupts-live-locked-operation",dir=>{var f=Backed(dir);f.Job.Status="Copying";f.Job.SourceVerified=false;Manifest(f.Engine,f.Job);MoveRecord(f.Engine,f.Job,"Running");using var held=new FileStream(Path.Combine(f.Engine.Root,"operation.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None);var doc=new WorkHistoryStore(Path.Combine(dir,"history.json")).Refresh([f.Engine.Root]);Check(doc.Records.Single(r=>r.Kind=="Backup").State=="Copying"&&doc.Records.Single(r=>r.Kind=="Move").State=="Running","Live operation was relabeled interrupted");});
        Test("ordinary-metadata-save-does-not-bypass-existing-old-folder",dir=>{var f=SelectiveRegisteredMove(dir);f.Library.SaveMetadata([f.Game],[],f.Inventory);var doc=f.Library.Load();f.Library.Reconcile(doc,f.Inventory,GameScanner.Scan(dir));Check(doc.Games.Single().LastKnownPath==f.Move.Source&&doc.Games.Single().Status=="LocationCheck","Unproven relocation silently bypassed conflict");});
        Test("observed-move-does-not-adopt-unrelated-previous-location",dir=>{var f=SelectiveRegisteredMove(dir);var unrelated=Path.Combine(dir,"unrelated");var doc=f.Library.SaveMetadata([f.Game],[],f.Inventory,new Dictionary<string,(string Source,string Destination)>{{f.Game.Id,(unrelated,f.Move.Destination)}}).Document;Check(doc.Games.Single().LastKnownPath==f.Move.Source,"Foreign transition changed library location");});
        Test("observed-move-keeps-restored-original-id-as-duplicate",dir=>{var f=SelectiveRegisteredMove(dir);File.Copy(Path.Combine(f.Move.Destination,LibraryStore.MarkerName),Path.Combine(f.Move.Source,LibraryStore.MarkerName));var doc=f.Library.SaveMetadata([f.Game],[],f.Inventory,new Dictionary<string,(string Source,string Destination)>{{f.Game.Id,(f.Move.Source,f.Move.Destination)}}).Document;Check(doc.Games.Single().LastKnownPath==f.Move.Source&&doc.Games.Single().Status=="Duplicate"&&f.Inventory.Locations[f.Game.Id].Count==2,"Recorded move hid restored original ID");});
        Test("observed-move-rechecks-destination-identity-before-adoption",dir=>{var f=SelectiveRegisteredMove(dir);LibraryStore.AssignCopyIdentity(f.Move.Destination,f.Game.Id);var doc=f.Library.SaveMetadata([f.Game],[],f.Inventory,new Dictionary<string,(string Source,string Destination)>{{f.Game.Id,(f.Move.Source,f.Move.Destination)}}).Document;Check(doc.Games.Single().LastKnownPath==f.Move.Source,"Changed destination identity was adopted using stale inventory");});
        Test("restart-recovers-selective-move-library-location-from-journal",dir=>{var p=Fixture(dir);Directory.CreateDirectory(Path.Combine(p.Source,"Extras"));File.WriteAllText(Path.Combine(p.Source,"Extras","keep.txt"),"excluded fixture");p.OmittedFolders=["Extras"];var old=p.Source;var w=Window(dir,p);Package? moved=null;try{Wait((Task)Call(w,"StartMoveBatchAsync",new List<Package>{p},Path.Combine(dir,"target"))!);Call(w,"FlushWorkspace");moved=Get<List<Package>>(w,"packages").Single(q=>q.Id==p.Id);Check(new LibraryStore(Path.Combine(dir,"library")).Load().Games.Single().LastKnownPath==moved.Source,"Completed selective move left stale library path");new LibraryStore(Path.Combine(dir,"library")).Update(doc=>{doc.Games.Single().LastKnownPath=old;doc.Games.Single().Status="External";});moved=JsonSerializer.Deserialize<Package>(JsonSerializer.Serialize(moved))!;}finally{Close(w);}var reopened=Window(dir,moved!);try{Set(reopened,"snapshot",null);Wait((Task)Call(reopened,"RefreshHistoryAsync")!);Wait((Task)Call(reopened,"SyncMovedPackagesAsync")!);Check(Get<Dictionary<string,(string Source,string Destination)>>(reopened,"observedMoveLocations").ContainsKey(moved!.Id),"Restart discarded already-applied move evidence");Wait((Task)Call(reopened,"RefreshWorkspaceAsync",moved.SearchRoot,false,false)!);var current=Get<List<Package>>(reopened,"packages").Single(q=>q.Id==moved.Id);Check(current.ReviewState.Length==0&&new LibraryStore(Path.Combine(dir,"library")).Load().Games.Single().LastKnownPath==moved.Source,"First scan after restart falsely requested relocation: "+current.ReviewState+" "+current.ReviewReason);Check(File.Exists(Path.Combine(old,"Extras","keep.txt")),"Excluded files changed");}finally{Close(reopened);}});
        Directory.CreateDirectory(Path.GetDirectoryName(report)!);File.WriteAllText(report,JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
